from itertools import combinations

def verify_bibd(blocks, v, k, lam):
    """Verify BIBD parameters"""
    b = len(blocks)
    r = lam * (v-1) // (k-1)

    # Check each block has k points
    for block in blocks:
        if len(block) != k:
            return False, f"Block {block} has wrong size"

    # Check each point appears in r blocks
    point_count = [0] * v
    for block in blocks:
        for p in block:
            point_count[p] += 1
    for i, cnt in enumerate(point_count):
        if cnt != r:
            return False, f"Point {i} appears {cnt} times, expected {r}"

    # Check each pair appears in lambda blocks
    pair_count = {}
    for block in blocks:
        for p1, p2 in combinations(block, 2):
            pair = (min(p1,p2), max(p1,p2))
            pair_count[pair] = pair_count.get(pair, 0) + 1

    for i in range(v):
        for j in range(i+1, v):
            pair = (i, j)
            cnt = pair_count.get(pair, 0)
            if cnt != lam:
                return False, f"Pair {pair} appears {cnt} times, expected {lam}"

    return True, "Valid BIBD"

# BIBD(18, 3, 2): Let's try using the structure of AG(2,3) - affine plane of order 3
# AG(2,3) has 9 points and 12 blocks (lines), each block has 3 points
# It's a BIBD(9, 3, 1)

# We can take two disjoint copies of AG(2,3) and add cross blocks
# Points: 0-8 (first copy), 9-17 (second copy)

# AG(2,3): points are (x,y) with x,y in GF(3) = {0,1,2}
# Lines: for each direction (slope) and intercept

def ag23_blocks():
    """Generate blocks of AG(2,3)"""
    blocks = []
    # Points: (x,y) -> 3*x + y, x,y in {0,1,2}

    # Horizontal lines: y = c
    for c in range(3):
        block = [3*x + c for x in range(3)]
        blocks.append(tuple(sorted(block)))

    # Lines with slope 0 (vertical): x = c  
    for c in range(3):
        block = [3*c + y for y in range(3)]
        blocks.append(tuple(sorted(block)))

    # Lines with slope 1: y = x + c (mod 3)
    for c in range(3):
        block = [3*x + ((x+c) % 3) for x in range(3)]
        blocks.append(tuple(sorted(block)))

    # Lines with slope 2: y = 2x + c (mod 3)
    for c in range(3):
        block = [3*x + ((2*x+c) % 3) for x in range(3)]
        blocks.append(tuple(sorted(block)))

    return blocks

