# Let me try a smarter hill climbing with simulated annealing
def simulated_annealing_bibd(v, k, lam, max_iter=500000, seed=42):
    r = lam * (v-1) // (k-1)
    b = lam * v * (v-1) // (k * (k-1))

    rng = random.Random(seed)

    all_blocks = list(combinations(range(v), k))
    all_blocks_set = set(all_blocks)

    # Start with a better initial solution
    # Use greedy to get a good start
    pair_count = {}
    for i in range(v):
        for j in range(i+1, v):
            pair_count[(i,j)] = 0
    point_count = [0] * v

    blocks = []
    remaining = list(all_blocks)
    rng.shuffle(remaining)

    # Greedy phase
    for block in remaining:
        if len(blocks) >= b:
            break
        feasible = all(point_count[p] < r for p in block)
        if not feasible:
            continue
        pairs_ok = all(pair_count[(min(p1,p2), max(p1,p2))] < lam 
                      for p1, p2 in combinations(block, 2))
        if not pairs_ok:
            continue
        blocks.append(block)
        for p in block:
            point_count[p] += 1
        for p1, p2 in combinations(block, 2):
            pair_count[(min(p1,p2), max(p1,p2))] += 1

    print(f"Greedy got {len(blocks)} blocks")

    # Fill remaining randomly
    blocks_set = set(blocks)
    remaining_set = all_blocks_set - blocks_set
    remaining_list = list(remaining_set)
    rng.shuffle(remaining_list)

    while len(blocks) < b:
        blocks.append(remaining_list.pop())
        blocks_set.add(blocks[-1])

    def compute_cost(blocks):
        pair_count = {}
        point_count = [0] * v
        for block in blocks:
            for p in block:
                point_count[p] += 1
            for p1, p2 in combinations(block, 2):
                pair = (min(p1,p2), max(p1,p2))
                pair_count[pair] = pair_count.get(pair, 0) + 1

        cost = 0
        for cnt in point_count:
            cost += abs(cnt - r)
        for i in range(v):
            for j in range(i+1, v):
                cnt = pair_count.get((i,j), 0)
                cost += abs(cnt - lam)
        return cost

    current_cost = compute_cost(blocks)
    print(f"Initial cost: {current_cost}")

    remaining_list = list(all_blocks_set - blocks_set)

    T = 5.0
    cooling = 0.9999

    for iteration in range(max_iter):
        if current_cost == 0:
            break

        T *= cooling

        # Swap a random block
        idx = rng.randint(0, b-1)
        old_block = blocks[idx]

        if not remaining_list:
            break

        new_idx = rng.randint(0, len(remaining_list)-1)
        new_block = remaining_list[new_idx]

        blocks[idx] = new_block
        new_cost = compute_cost(blocks)

        delta = new_cost - current_cost

        if delta <= 0 or rng.random() < (2.718 ** (-delta / max(T, 0.001))):
            # Accept
            remaining_list[new_idx] = old_block
            blocks_set.discard(old_block)
            blocks_set.add(new_block)
            current_cost = new_cost
        else:
            # Reject
            blocks[idx] = old_block

        if iteration % 50000 == 0:
            print(f"Iter {iteration}: cost = {current_cost}, T = {T:.4f}")

    return blocks if current_cost == 0 else None

print("Trying simulated annealing...")
result = simulated_annealing_bibd(18, 3, 2, max_iter=500000)
if result:
    valid, msg = verify_bibd(result, 18, 3, 2)
    print(f"Valid: {valid}, {msg}")
else:
    print("SA failed")
